const wildlife=[['African elephant','Loxodonta africana','Mammal','🐘','Savanna · woodland · wetland'],['Forest elephant','Loxodonta cyclotis','Mammal','🐘','Central & West African forest'],['Lion','Panthera leo','Mammal','🦁','Savanna · woodland'],['Leopard','Panthera pardus','Mammal','🐆','Forest · savanna · mountain'],['Cheetah','Acinonyx jubatus','Mammal','🐆','Open grassland'],['Black rhinoceros','Diceros bicornis','Mammal','🦏','Bushland · desert'],['White rhinoceros','Ceratotherium simum','Mammal','🦏','Grassland · savanna'],['Hippopotamus','Hippopotamus amphibius','Mammal','🦛','Rivers · lakes · wetlands'],['Giraffe','Giraffa spp.','Mammal','🦒','Savanna · woodland'],['Plains zebra','Equus quagga','Mammal','🦓','Grassland · savanna'],['Mountain gorilla','Gorilla beringei beringei','Mammal','🦍','Montane forest'],['Chimpanzee','Pan troglodytes','Mammal','🐒','Tropical forest'],['Ring-tailed lemur','Lemur catta','Mammal','🐒','Southern Madagascar'],['African buffalo','Syncerus caffer','Mammal','🐃','Savanna · forest'],['Blue wildebeest','Connochaetes taurinus','Mammal','🐂','Open grassland'],['Spotted hyena','Crocuta crocuta','Mammal','🐕','Savanna · woodland'],['African wild dog','Lycaon pictus','Mammal','🐕','Savanna · woodland'],['Meerkat','Suricata suricatta','Mammal','🐾','Arid grassland'],['Pangolin','Smutsia spp.','Mammal','🐾','Forest · savanna'],['Greater kudu','Tragelaphus strepsiceros','Mammal','🦌','Woodland · bushland'],['Sable antelope','Hippotragus niger','Mammal','🦌','Woodland · grassland'],['Nile crocodile','Crocodylus niloticus','Reptile','🐊','Rivers · lakes'],['Nile monitor','Varanus niloticus','Reptile','🦎','Wetlands · riverbanks'],['African rock python','Python sebae','Reptile','🐍','Savanna · forest'],['Leopard tortoise','Stigmochelys pardalis','Reptile','🐢','Savanna · grassland'],['Ostrich','Struthio camelus','Bird','🪶','Open country · desert'],['Secretarybird','Sagittarius serpentarius','Bird','🦅','Grassland · savanna'],['African fish eagle','Haliaeetus vocifer','Bird','🦅','Lakes · rivers'],['Saddle-billed stork','Ephippiorhynchus senegalensis','Bird','🐦','Wetlands'],['Southern ground hornbill','Bucorvus leadbeateri','Bird','🐦','Savanna · woodland'],['Lilac-breasted roller','Coracias caudatus','Bird','🐦','Open woodland'],['Grey crowned crane','Balearica regulorum','Bird','🐦','Wetlands · grassland'],['Shoebill','Balaeniceps rex','Bird','🐦','Papyrus swamps'],['Greater flamingo','Phoenicopterus roseus','Bird','🦩','Salt lakes · lagoons'],['Kori bustard','Ardeotis kori','Bird','🐦','Open savanna'],['Vulturine guineafowl','Acryllium vulturinum','Bird','🐦','Dry bushland']];const animalGrid=document.getElementById('animalGrid'),animalSearch=document.getElementById('animalSearch');let animalKind='all';function renderWildlife(){const q=animalSearch.value.toLowerCase().trim();const rows=wildlife.filter(a=>(animalKind==='all'||a[2]===animalKind)&&(!q||a.join(' ').toLowerCase().includes(q)));animalGrid.innerHTML=rows.length?rows.map(a=>`<article><div class="animal-emoji">${a[3]}</div><div><h2>${a[0]}</h2><p>${a[1]}</p><div class="animal-meta"><span>${a[2]}</span><span>${a[4]}</span></div></div></article>`).join(''):'<div class="animal-empty">No species matches that search.</div>'}document.querySelectorAll('#wildlifeFilters button').forEach(button=>button.addEventListener('click',()=>{animalKind=button.dataset.kind;document.querySelectorAll('#wildlifeFilters button').forEach(x=>x.classList.toggle('selected',x===button));renderWildlife()}));animalSearch.addEventListener('input',renderWildlife);renderWildlife();
